import{_ as p,a0 as d,w as o,s as r,I as t,x as e,a1 as a,A as n,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"LFCS 系列第十一講：如何使用命令 vgcreate、lvcreate 和 lvextend 管理和創建 LVM | LCTT x X-CMD","titleTemplate":false,"description":"LFCS 系列第十一講：如何使用命令 vgcreate、lvcreate 和 lvextend 管理和創建 LVM | LCTT (LFCS) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"LFCS 系列第十一講：如何使用命令 vgcreate、lvcreate 和 lvextend 管理和創建 LVM | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"LFCS 系列第十一講：如何使用命令 vgcreate、lvcreate 和 lvextend 管理和創建 LVM | LCTT (LFCS) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"LFCS/Part 11 - How to Manage and Create LVM Using vgcreate, lvcreate and lvextend Commands","title":"LFCS 系列第十一講：如何使用命令 vgcreate、lvcreate 和 lvextend 管理和創建 LVM","tag":"LFCS","desc":""},"relativePath":"LFCS/Part 11 - How to Manage and Create LVM Using vgcreate, lvcreate and lvextend Commands.md","filePath":"[post].md"}'),g={name:"LFCS/Part 11 - How to Manage and Create LVM Using vgcreate, lvcreate and lvextend Commands.md"};function h(c,s,k,u,v,b){const i=d("Link");return o(),r("div",null,[s[33]||(s[33]=t("h1",{id:"lfcs-系列第十一講-如何使用命令-vgcreate、lvcreate-和-lvextend-管理和創建-lvm",tabindex:"-1"},[e("LFCS 系列第十一講：如何使用命令 vgcreate、lvcreate 和 lvextend 管理和創建 LVM "),t("a",{class:"header-anchor",href:"#lfcs-系列第十一講-如何使用命令-vgcreate、lvcreate-和-lvextend-管理和創建-lvm","aria-label":"Permalink to “LFCS 系列第十一講：如何使用命令 vgcreate、lvcreate 和 lvextend 管理和創建 LVM”"},"​")],-1)),t("p",null,[s[2]||(s[2]=e("由於 LFCS 考試中的一些改變已在 2016 年 2 月 2 日生效，我們添加了一些必要的專題到 ",-1)),a(i,{href:"https://linux.cn/article-7161-1.html"},{default:n(()=>[...s[0]||(s[0]=[e("LFCS 系列",-1)])]),_:1}),s[3]||(s[3]=e("。我們也非常推薦備考的同學，同時閲讀 ",-1)),a(i,{href:"http://www.tecmint.com/installing-network-services-and-configuring-services-at-system-boot/"},{default:n(()=>[...s[1]||(s[1]=[e("LFCE 系列",-1)])]),_:1}),s[4]||(s[4]=e("。",-1))]),s[34]||(s[34]=l('<p><img src="http://www.tecmint.com/wp-content/uploads/2016/03/Manage-LVM-and-Create-LVM-Partition-in-Linux.png" alt=""></p><p><em>LFCS：管理 LVM 和創建 LVM 分區</em></p><p>在安裝 Linux 系統的時候要做的最重要的決定之一便是給系統文件、home 目錄等分配空間。在這個地方犯了錯，再要擴大空間不足的分區，那樣既麻煩又有風險。</p><p><strong>邏輯卷管理</strong> （<strong>LVM</strong>）相較於傳統的分區管理有許多優點，已經成為大多數（如果不能説全部的話） Linux 發行版安裝時的默認選擇。LVM 最大的優點應該是能方便的按照你的意願調整（減小或增大）邏輯分區的大小。</p><p>LVM 的組成結構：</p><ul><li>把一塊或多塊硬盤或者一個或多個分區配置成物理卷（PV）。</li><li>一個用一個或多個物理卷創建出的卷組（<strong>VG</strong>）。可以把一個卷組想像成一個單獨的存儲單元。</li><li>在一個卷組上可以創建多個邏輯卷。每個邏輯卷相當於一個傳統意義上的分區 —— 優點是它的大小可以根據需求重新調整大小，正如之前提到的那樣。</li></ul><p>本文，我們將使用三塊 <strong>8 GB</strong> 的磁盤（<strong>/dev/sdb</strong>、<strong>/dev/sdc</strong> 和 <strong>/dev/sdd</strong>）分別創建三個物理卷。你既可以直接在整個設備上創建 PV，也可以先分區在創建。</p>',7)),t("p",null,[s[6]||(s[6]=e("在這裏我們選擇第一種方式，如果你決定使用第二種（可以參考本系列",-1)),a(i,{href:"https://linux.cn/article-7187-1.html"},{default:n(()=>[...s[5]||(s[5]=[e("第四講：創建分區和文件系統",-1)])]),_:1}),s[7]||(s[7]=e("）確保每個分區的類型都是 ",-1)),s[8]||(s[8]=t("code",null,"8e",-1)),s[9]||(s[9]=e("。",-1))]),s[35]||(s[35]=l(`<h3 id="創建物理卷-卷組和邏輯卷" tabindex="-1">創建物理卷，卷組和邏輯卷 <a class="header-anchor" href="#創建物理卷-卷組和邏輯卷" aria-label="Permalink to “創建物理卷，卷組和邏輯卷”">​</a></h3><p>要在 <strong>/dev/sdb</strong>、<strong>/dev/sdc</strong> 和 <strong>/dev/sdd</strong>上創建物理卷，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># pvcreate /dev/sdb /dev/sdc /dev/sdd</span></span></code></pre></div><p>你可以列出新創建的 PV ，通過：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># pvs</span></span></code></pre></div><p>並得到每個 PV 的詳細信息，通過：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># pvdisplay /dev/sdX</span></span></code></pre></div><p>（<strong>X</strong> 即 b、c 或 d）</p><p>如果沒有輸入 <code>/dev/sdX</code> ，那麼你將得到所有 PV 的信息。</p><p>使用 /dev/sdb<code>和</code>/dev/sdc<code>創建卷組 ，命名為</code>vg00<code>(在需要時是可以通過添加其他設備來擴展空間的，我們等到説明這點的時候再用，所以暫時先保留</code>/dev/sdd\`）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vgcreate vg00 /dev/sdb /dev/sdc</span></span></code></pre></div><p>就像物理卷那樣，你也可以查看卷組的信息，通過：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vgdisplay vg00</span></span></code></pre></div><p>由於 <code>vg00</code> 是由兩個 <strong>8 GB</strong> 的磁盤組成的，所以它將會顯示成一個 <strong>16 GB</strong> 的硬盤：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2016/03/List-LVM-Volume-Groups.png" alt=""></p><p><em>LVM 卷組列表</em></p><p>當談到創建邏輯卷，空間的分配必須考慮到當下和以後的需求。根據每個邏輯卷的用途來命名是一個好的做法。</p><p>舉個例子，讓我們創建兩個 LV，命名為 <code>vol_projects</code> （<strong>10 GB</strong>） 和 <code>vol_backups</code> （剩下的空間）， 在日後分別用於部署項目文件和系統備份。</p><p>參數 <code>-n</code> 用於為 LV 指定名稱，而 <code>-L</code> 用於設定固定的大小，還有 <code>-l</code> （小寫的 L）在 VG 的預留空間中用於指定百分比大小的空間。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># lvcreate -n vol_projects -L 10G vg00</span></span>
<span class="line"><span># lvcreate -n vol_backups -l 100%FREE vg00</span></span></code></pre></div><p>和之前一樣，你可以查看 LV 的列表和基礎信息，通過：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># lvs</span></span></code></pre></div><p>或是查看詳細信息，通過：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># lvdisplay</span></span></code></pre></div><p>若要查看單個 <strong>LV</strong> 的信息，使用 <strong>lvdisplay</strong> 加上 <strong>VG</strong> 和 <strong>LV</strong> 作為參數，如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># lvdisplay vg00/vol_projects</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/03/List-Logical-Volume.png" alt=""></p><p><em>邏輯卷列表</em></p><p>如上圖，我們看到 LV 已經被創建成存儲設備了（參考 LV Path 那一行）。在使用每個邏輯卷之前，需要先在上面創建文件系統。</p><p>這裏我們拿 ext4 來做舉例，因為對於每個 LV 的大小， ext4 既可以增大又可以減小（相對的 xfs 就只允許增大）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mkfs.ext4 /dev/vg00/vol_projects</span></span>
<span class="line"><span># mkfs.ext4 /dev/vg00/vol_backups</span></span></code></pre></div><p>我們將在下一節向大家説明，如何調整邏輯卷的大小並在需要的時候添加額外的外部存儲空間。</p><h3 id="調整邏輯卷大小和擴充卷組" tabindex="-1">調整邏輯卷大小和擴充卷組 <a class="header-anchor" href="#調整邏輯卷大小和擴充卷組" aria-label="Permalink to “調整邏輯卷大小和擴充卷組”">​</a></h3><p>現在設想以下場景。<code>vol_backups</code> 中的空間即將用完，而 <code>vol_projects</code> 中還有富餘的空間。由於 LVM 的特性，我們可以輕易的減小後者的大小（比方説 <strong>2.5 GB</strong>），並將其分配給前者，與此同時調整每個文件系統的大小。</p><p>幸運的是這很簡單，只需：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># lvreduce -L -2.5G -r /dev/vg00/vol_projects</span></span>
<span class="line"><span># lvextend -l +100%FREE -r /dev/vg00/vol_backups</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/03/Resize-Reduce-Logical-Volume-and-Volume-Group.png" alt=""></p><p><em>減小邏輯卷和卷組</em></p><p>在調整邏輯卷的時候，其中包含的減號 <code>(-)</code> 或加號 <code>(+)</code> 是十分重要的。否則 LV 將會被設置成指定的大小，而非調整指定大小。</p><p>有些時候，你可能會遭遇那種無法僅靠調整邏輯卷的大小就可以解決的問題，那時你就需要購置額外的存儲設備了，你可能需要再加一塊硬盤。這裏我們將通過添加之前配置時預留的 PV （<code>/dev/sdd</code>），用以模擬這種情況。</p><p>想把 <code>/dev/sdd</code> 加到 <code>vg00</code>，執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vgextend vg00 /dev/sdd</span></span></code></pre></div><p>如果你在運行上條命令的前後執行 vgdisplay <code>vg00</code> ，你就會看出 VG 的大小增加了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vgdisplay vg00</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/03/List-Volume-Group-Size.png" alt=""></p><p><em>查看卷組磁盤大小</em></p><p>現在，你可以使用新加的空間，按照你的需求調整現有 LV 的大小，或者創建一個新的 LV。</p><h3 id="在啓動和需求時掛載邏輯卷" tabindex="-1">在啓動和需求時掛載邏輯卷 <a class="header-anchor" href="#在啓動和需求時掛載邏輯卷" aria-label="Permalink to “在啓動和需求時掛載邏輯卷”">​</a></h3><p>當然，如果我們不打算實際的使用邏輯卷，那麼創建它們就變得毫無意義了。為了更好的識別邏輯卷，我們需要找出它的 <code>UUID</code> （用於識別一個格式化存儲設備的唯一且不變的屬性）。</p><p>要做到這點，可使用 blkid 加每個設備的路徑來實現：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># blkid /dev/vg00/vol_projects</span></span>
<span class="line"><span># blkid /dev/vg00/vol_backups</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/03/Find-Logical-Volume-UUID.png" alt=""></p><p><em>尋找邏輯卷的 UUID</em></p><p>為每個 LV 創建掛載點：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mkdir /home/projects</span></span>
<span class="line"><span># mkdir /home/backups</span></span></code></pre></div><p>並在 <code>/etc/fstab</code> 插入相應的條目（確保使用之前獲得的UUID）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>UUID=b85df913-580f-461c-844f-546d8cde4646 /home/projects    ext4 defaults 0 0</span></span>
<span class="line"><span>UUID=e1929239-5087-44b1-9396-53e09db6eb9e /home/backups ext4    defaults 0 0</span></span></code></pre></div><p>保存並掛載 LV：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mount -a</span></span>
<span class="line"><span># mount | grep home</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/03/Mount-Logical-Volumes-on-Linux-1.png" alt=""></p><p><em>掛載邏輯卷</em></p>`,61)),t("p",null,[s[11]||(s[11]=e("在涉及到 LV 的實際使用時，你還需要按照曾在本系列",-1)),a(i,{href:"https://linux.cn/article-7418-1.html"},{default:n(()=>[...s[10]||(s[10]=[e("第八講：管理用户和用户組",-1)])]),_:1}),s[12]||(s[12]=e("中講解的那樣，為其設置合適的 ",-1)),s[13]||(s[13]=t("code",null,"ugo+rwx",-1)),s[14]||(s[14]=e("。",-1))]),s[36]||(s[36]=t("h3",{id:"總結",tabindex:"-1"},[e("總結 "),t("a",{class:"header-anchor",href:"#總結","aria-label":"Permalink to “總結”"},"​")],-1)),t("p",null,[s[17]||(s[17]=e("本文介紹了 ",-1)),a(i,{href:"https://linux.cn/article-3965-1.html"},{default:n(()=>[...s[15]||(s[15]=[e("邏輯卷管理",-1)])]),_:1}),s[18]||(s[18]=e("，一個用於管理可擴展存儲設備的多功能工具。與 RAID（曾在本系列講解過的 ",-1)),a(i,{href:"https://linux.cn/article-7229-1.html"},{default:n(()=>[...s[16]||(s[16]=[e("第六講：組裝分區為RAID設備——創建和管理系統備份",-1)])]),_:1}),s[19]||(s[19]=e("）結合使用，你將同時體驗到（LVM 帶來的）可擴展性和（RAID 提供的）冗餘。",-1))]),s[37]||(s[37]=t("p",null,[e("在這類的部署中，你通常會在 "),t("code",null,"RAID"),e(" 上發現 "),t("code",null,"LVM"),e("，這就是説，要先配置好 RAID 然後它在上面配置 LVM。")],-1)),s[38]||(s[38]=t("p",null,"如果你對本問有任何的疑問和建議，可以直接在下方的評論區告訴我們。",-1)),s[39]||(s[39]=t("hr",null,null,-1)),t("p",null,[s[21]||(s[21]=e("via: ",-1)),a(i,{href:"http://www.tecmint.com/manage-and-create-lvm-parition-using-vgcreate-lvcreate-and-lvextend/"},{default:n(()=>[...s[20]||(s[20]=[e("http://www.tecmint.com/manage-and-create-lvm-parition-using-vgcreate-lvcreate-and-lvextend/",-1)])]),_:1})]),t("p",null,[s[25]||(s[25]=e("作者：",-1)),a(i,{href:"http://www.tecmint.com/author/gacanepa/"},{default:n(()=>[...s[22]||(s[22]=[e("Gabriel Cánepa",-1)])]),_:1}),s[26]||(s[26]=e(" 譯者：",-1)),a(i,{href:"https://github.com/martin2011qi"},{default:n(()=>[...s[23]||(s[23]=[e("martin2011qi",-1)])]),_:1}),s[27]||(s[27]=e(" 校對：",-1)),a(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[24]||(s[24]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[30]||(s[30]=e("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[28]||(s[28]=[e("LCTT",-1)])]),_:1}),s[31]||(s[31]=e(" 原創翻譯，",-1)),a(i,{href:"https://linux.cn/"},{default:n(()=>[...s[29]||(s[29]=[e("Linux中國",-1)])]),_:1}),s[32]||(s[32]=e(" 榮譽推出",-1))])])}const C=p(g,[["render",h]]);export{L as __pageData,C as default};
